const densityMap = {
  'coarse mesh': 12,
  'sparse gauze': 15,
  'open linen': 18,
  'taut muslin': 22,
  'fine cambric': 26,
  'dense silk': 30
};

const elasticityMap = {
  'slack cord': { k: 0.05, damp: 0.96, snap: 85 },
  'braided cotton': { k: 0.12, damp: 0.93, snap: 70 },
  'tempered nylon': { k: 0.25, damp: 0.88, snap: 55 },
  'drawn wire': { k: 0.50, damp: 0.82, snap: 42 },
  'brittle tungsten': { k: 0.80, damp: 0.70, snap: 30 },
  'glass filament': { k: 1.05, damp: 0.60, snap: 18 }
};

const shearMap = {
  'gentle thermals': { f: 1.5, v: 1, r: 150 },
  'meandering drift': { f: 2.5, v: 1, r: 200 },
  'surging gusts': { f: 4.0, v: 2, r: 250 },
  'twisting vortex': { f: 5.5, v: 2, r: 300 },
  'shearing cyclone': { f: 7.5, v: 3, r: 350 },
  'violent squall': { f: 9.5, v: 4, r: 400 }
};

const mendMap = {
  'creeping scar': 380,
  'sluggish knit': 240,
  'steady weave': 150,
  'swift knitting': 60,
  'instant suture': 12,
  'hypertrophic fuse': 1
};

const colorMap = {
  'electric cyan': { base: '#005599', strain: '#00E5FF', spark: '#FFFFFF' },
  'radium emerald': { base: '#006633', strain: '#39FF14', spark: '#A8FFB2' },
  'solar amber': { base: '#663300', strain: '#FF9E00', spark: '#FFF4CC' },
  'charged violet': { base: '#550088', strain: '#B829DD', spark: '#FF80DF' },
  'crimson corona': { base: '#770011', strain: '#FF1744', spark: '#FFB3BA' },
  'ghost white': { base: '#555555', strain: '#8E99A4', spark: '#FFFFFF' }
};

let currentDensity = 0;
let nodes = [];
let springs = [];

p.setup = function() {
  p.createCanvas(800, 800);
};

function initGrid(dim, width, height) {
  nodes = [];
  springs = [];
  const spacingX = width / (dim - 1);
  const spacingY = height / (dim - 1);

  for(let y = 0; y < dim; y++) {
    for(let x = 0; x < dim; x++) {
      nodes.push({
        x: x * spacingX,
        y: y * spacingY,
        vx: 0, 
        vy: 0,
        nx: 0,
        ny: 0,
        pinned: (x === 0 || x === dim - 1 || y === 0 || y === dim - 1)
      });
    }
  }

  for(let y = 0; y < dim; y++) {
    for(let x = 0; x < dim; x++) {
      let i = y * dim + x;
      if(x < dim - 1) springs.push({a: i, b: i + 1, rest: spacingX, active: true, timer: 0, stretch: 0});
      if(y < dim - 1) springs.push({a: i, b: i + dim, rest: spacingY, active: true, timer: 0, stretch: 0});
    }
  }
  currentDensity = dim;
}

p.draw = function() {
  const vDen = p.getSynthVar('weave_density') || 'taut muslin';
  const vEla = p.getSynthVar('thread_elasticity') || 'tempered nylon';
  const vShe = p.getSynthVar('shear_vortex') || 'twisting vortex';
  const vMen = p.getSynthVar('mending_tempo') || 'swift knitting';
  const vCol = p.getSynthVar('phosphor_bloom') || 'electric cyan';

  let dim = densityMap[vDen] || 22;
  if(dim !== currentDensity) {
    initGrid(dim, p.width, p.height);
  }

  let ela = elasticityMap[vEla];
  let she = shearMap[vShe];
  let men = mendMap[vMen];
  let cols = colorMap[vCol];

  let ctx = p.drawingContext;
  ctx.globalCompositeOperation = 'source-over';
  p.background(5, 5, 10, 255);
  ctx.globalCompositeOperation = 'lighter';

  let t = p.frameCount * 0.01;
  let pulseSpeed = p.frameCount * 2.5;

  // Pre-calculate noise per node once per frame
  for(let i = 0; i < nodes.length; i++) {
    let n = nodes[i];
    if(!n.pinned) {
      n.nx = p.noise(n.x * 0.01, n.y * 0.01, t) - 0.5;
      n.ny = p.noise(n.x * 0.01 + 100, n.y * 0.01 + 100, t) - 0.5;
    }
  }

  for(let step = 0; step < 2; step++) {
    for(let i = 0; i < nodes.length; i++) {
      let n = nodes[i];
      if(n.pinned) continue;

      n.vx += n.nx * (she.f * 0.2 + 0.8);
      n.vy += n.ny * (she.f * 0.2 + 0.8);

      for(let v = 0; v < she.v; v++) {
        let cx = p.width / 2 + Math.sin(t * (1.1 + v)) * (p.width * 0.4);
        let cy = p.height / 2 + Math.cos(t * (0.9 + v)) * (p.height * 0.4);
        let dx = cx - n.x;
        let dy = cy - n.y;
        let d = Math.sqrt(dx * dx + dy * dy);

        if(d > 0 && d < she.r) {
          let force = (1 - d / she.r) * she.f * 0.2;
          n.vx += (-dy / d) * force;
          n.vy += (dx / d) * force;
          n.vx += (dx / d) * force * 0.2;
          n.vy += (dy / d) * force * 0.2;
        }
      }
    }

    for(let i = 0; i < springs.length; i++) {
      let s = springs[i];
      if(!s.active) continue;
      let a = nodes[s.a];
      let b = nodes[s.b];

      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let d = Math.sqrt(dx * dx + dy * dy);

      if(d > s.rest + ela.snap) {
        s.active = false;
        s.timer = men;
        continue;
      }

      let diff = (d - s.rest) / Math.max(d, 0.01);
      let fx = dx * diff * ela.k * 0.5;
      let fy = dy * diff * ela.k * 0.5;
      if(!a.pinned) { a.vx += fx; a.vy += fy; }
      if(!b.pinned) { b.vx -= fx; b.vy -= fy; }
    }

    for(let i = 0; i < nodes.length; i++) {
      let n = nodes[i];
      if(n.pinned) continue;
      n.vx *= ela.damp;
      n.vy *= ela.damp;

      n.vx = Math.max(-25, Math.min(25, n.vx));
      n.vy = Math.max(-25, Math.min(25, n.vy));

      n.x += n.vx;
      n.y += n.vy;
    }
  }

  // Pre-calculate rendering distances once per spring
  for(let i = 0; i < springs.length; i++) {
    let s = springs[i];
    if(s.active) {
      let a = nodes[s.a];
      let b = nodes[s.b];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      s.stretch = Math.abs(Math.sqrt(dx * dx + dy * dy) - s.rest);
    }
  }

  let sparkPoints = [];

  ctx.beginPath();
  for(let i = 0; i < springs.length; i++) {
    let s = springs[i];
    let a = nodes[s.a];
    let b = nodes[s.b];

    if(!s.active) {
      s.timer--;
      if(s.timer <= 0) s.active = true;
      else {
        let shrink = s.timer / men;
        let midX = (a.x + b.x) * 0.5;
        let midY = (a.y + b.y) * 0.5;
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(a.x + (midX - a.x) * (1 - shrink), a.y + (midY - a.y) * (1 - shrink));
        ctx.moveTo(b.x, b.y);
        ctx.lineTo(b.x + (midX - b.x) * (1 - shrink), b.y + (midY - b.y) * (1 - shrink));

        if(s.timer > men - 15) {
          sparkPoints.push(a, b);
        }
      }
      continue;
    }

    if (s.stretch <= ela.snap * 0.5) {
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
    }
  }
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = cols.base;
  ctx.stroke();

  ctx.beginPath();
  for(let i = 0; i < springs.length; i++) {
    let s = springs[i];
    if(!s.active) continue;
    let a = nodes[s.a];
    if ((a.x + a.y - pulseSpeed) % 250 < 40) {
      let b = nodes[s.b];
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
    }
  }
  ctx.lineWidth = 3.5;
  ctx.strokeStyle = cols.spark;
  ctx.stroke();

  ctx.beginPath();
  for(let i = 0; i < springs.length; i++) {
    let s = springs[i];
    if(!s.active) continue;

    if (s.stretch > ela.snap * 0.5) {
      let a = nodes[s.a];
      let b = nodes[s.b];
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
    }
  }
  ctx.lineWidth = 4.0;
  ctx.strokeStyle = cols.strain;
  ctx.stroke();

  if (sparkPoints.length > 0) {
    ctx.fillStyle = cols.spark;
    for(let i = 0; i < sparkPoints.length; i++) {
      ctx.fillRect(sparkPoints[i].x - 1.5, sparkPoints[i].y - 1.5, 4, 4);
    }
  }
};
